"""Synthetic retrieval history for the MVP predictor.

**This is not operational data.** Every row here is generated by the function
below from a process this file defines, so the model trained on it learns that
process and nothing about how any real valet team works. The training script
prints a warning to that effect and the disclaimer travels into the saved
artifact, because a mean absolute error computed against synthetic "actuals" is
a measurement of fit to this generator -- not of predictive power in the field.

Why generate it at all, rather than fitting on the platform's own rows:

A fresh checkout has one seeded custody session. Fitting a model on one row
would produce a number that looks like an estimate and is really a constant.
Generating a few thousand labelled episodes is the honest way to have something
to fit and, more importantly, something to *evaluate against* -- the MAE reported
by ``evaluate_retrieval_model.py`` only means something because there are held-out
rows the model never saw.

Two properties are built in deliberately:

* **Irreducible noise.** Real retrieval has variance this model cannot see --
  a driver who left the keys in the boot, a car parked nose-in behind another.
  The generator adds lognormal noise, so MAE stays above zero. An earlier
  classifier in this project scored a perfect 1.00 on synthetic data, which was
  not a success: the classes did not overlap, so one threshold on one feature
  would have done as well. A regression that fits its training data exactly is
  the same mistake in a different costume.
* **A temporal split.** Retrieval demand drifts over a day and a week. Splitting
  randomly would let the model see Friday evenings in training and be scored on
  Friday evenings in test, flattering the result. Rows are split by time
  instead, so evaluation happens on a later period than training.
"""

from __future__ import annotations

import json
import math
import zlib
from collections.abc import Sequence
from dataclasses import dataclass
from datetime import datetime, timedelta
from pathlib import Path

import numpy as np

from ai.retrieval.features import (
    RETRIEVAL_FEATURE_COLUMNS,
    RetrievalContext,
    extract_features,
)

#: How long one valet needs to reach a car and bring it to the handover point,
#: before any queueing. Split into walk-out and drive-back so the two can scale
#: differently with zone size.
BASE_WALK_MINUTES = 2.4
BASE_DRIVE_MINUTES = 1.8

#: Added minutes per vehicle already ahead in the queue, per available valet.
QUEUE_SERVICE_MINUTES = 3.2

#: A flagged vehicle needs a manager to clear the flag before it can be handed
#: over. This is a real step in the workflow, not an invented penalty.
FLAGGED_PENALTY_MINUTES = 4.5

#: Zone shapes. ``walk_scale`` stands in for how far the zone sits from the
#: handover point -- the platform has no yard map, so this is the honest
#: placeholder, and it is varied across zones rather than assumed constant.
ZONE_PROFILES: tuple[dict[str, float], ...] = (
    {"walk_scale": 0.8, "capacity": 12},
    {"walk_scale": 1.0, "capacity": 20},
    {"walk_scale": 1.35, "capacity": 30},
    {"walk_scale": 1.7, "capacity": 45},
)

#: Multiplier by hour of day. Evening peaks are when everyone leaves at once;
#: the small hours are quiet. Applied multiplicatively because contention
#: stretches the whole process rather than adding a fixed delay.
def _peak_factor(hour: float) -> float:
    if 8.0 <= hour < 10.0:
        return 1.25
    if 12.0 <= hour < 14.0:
        return 1.15
    if 17.0 <= hour < 21.0:
        return 1.45
    if 0.0 <= hour < 6.0:
        return 0.85
    return 1.0


@dataclass(frozen=True)
class RetrievalEpisode:
    """One labelled historical retrieval: its features and what actually happened."""

    features: dict[str, float]
    actual_minutes: float
    requested_at: datetime
    zone_index: int
    #: Provenance, not model input. The model consumes ``features``; these three
    #: exist so an exported row is readable and so ``load_history`` can rebuild
    #: an episode without loss.
    zone_code: str = ""
    vehicle_status: str = "IN_CUSTODY"
    zone_occupancy: int = 0

    def as_row(self) -> dict[str, float | str]:
        row: dict[str, float | str] = {
            name: self.features[name] for name in RETRIEVAL_FEATURE_COLUMNS
        }
        # Full precision, deliberately not rounded. This is the label the model
        # is scored against, so an exported history must reload byte-for-byte;
        # rounding here would make ``load_history`` a lossy copy and quietly
        # change the MAE depending on whether it was regenerated or loaded.
        row["actual_retrieval_minutes"] = self.actual_minutes
        row["requested_at"] = self.requested_at.isoformat()
        row["zone_index"] = self.zone_index
        # Provenance, not model input: ``zone_code`` and ``vehicle_status`` are
        # what a human reading the exported file needs to make sense of a row,
        # and they let ``load_history`` rebuild an episode exactly. The numeric
        # zone index is what the model sees; the code is what the operator sees.
        row["zone_code"] = self.zone_code
        row["vehicle_status"] = self.vehicle_status
        # The raw count, alongside the percentage the model actually uses. Kept
        # because the percent is rounded and cannot be inverted exactly, and
        # ``load_history`` has to reconstruct the episode without loss.
        row["zone_occupancy"] = self.zone_occupancy
        return row


@dataclass(frozen=True)
class RetrievalDataset:
    """Generated history plus the indices of the held-out period."""

    episodes: tuple[RetrievalEpisode, ...]
    X: np.ndarray
    y: np.ndarray
    test_mask: np.ndarray
    generated_at: str

    @property
    def rows(self) -> int:
        return len(self.episodes)

    def summary(self) -> dict[str, float | int | str]:
        train_y = self.y[~self.test_mask]
        test_y = self.y[self.test_mask]
        return {
            "rows": self.rows,
            "train_rows": int((~self.test_mask).sum()),
            "test_rows": int(self.test_mask.sum()),
            "train_mean_minutes": float(np.mean(train_y)) if train_y.size else 0.0,
            "test_mean_minutes": float(np.mean(test_y)) if test_y.size else 0.0,
            "min_minutes": float(np.min(self.y)) if self.y.size else 0.0,
            "max_minutes": float(np.max(self.y)) if self.y.size else 0.0,
            "generated_at": self.generated_at,
            "source": "synthetic - see the module docstring",
        }


def _zone_index_for(zone_code: str) -> int:
    """Map a zone code onto one of the profiles, deterministically.

    A stable hash rather than a lookup table, so an unseen zone code still gets
    a consistent profile instead of failing. The platform lets managers create
    zones freely; a predictor that crashes on a new one would be worse than one
    that approximates.

    **It must not use the builtin ``hash()``.** Python salts string hashes per
    process, so ``hash("ZONE-A")`` differs on every run -- training would fit
    one mapping while the live service served predictions under another, and
    nothing would error. ``zlib.crc32`` is fixed by definition.
    """
    return zlib.crc32(zone_code.encode("utf-8")) % len(ZONE_PROFILES)


def _true_minutes(
    *,
    queue_position: int,
    active_valets: int,
    zone_profile: dict[str, float],
    occupancy_percent: float,
    requested_at: datetime,
    vehicle_flagged: bool,
) -> float:
    """The noise-free relationship the generator believes in.

    Exposed so tests can assert the model recovers the shape of it, rather than
    only checking that some number came out.
    """
    valets = max(1, active_valets)
    queue_wait = (max(1, queue_position) - 1) * QUEUE_SERVICE_MINUTES / valets
    walk = BASE_WALK_MINUTES * zone_profile["walk_scale"]
    drive = BASE_DRIVE_MINUTES * zone_profile["walk_scale"]
    # A crowded yard is slower to manoeuvre through, but the effect saturates:
    # going from 20% to 40% full matters more than 80% to 100%.
    crowding = 2.6 * math.sqrt(max(0.0, occupancy_percent) / 100.0)
    peak = _peak_factor(requested_at.hour + requested_at.minute / 60.0)
    flagged = FLAGGED_PENALTY_MINUTES if vehicle_flagged else 0.0
    weekend = 1.1 if requested_at.weekday() >= 5 else 1.0

    base = walk + drive + queue_wait + crowding + flagged
    return max(1.0, base * peak * weekend)


def generate_history(
    *,
    episodes: int = 4000,
    seed: int = 20260909,
    start: datetime | None = None,
    span_days: int = 90,
    test_fraction: float = 0.25,
    zone_codes: tuple[str, ...] = ("ZONE-A", "ZONE-B", "ZONE-C", "ZONE-D"),
) -> RetrievalDataset:
    """Generate ``episodes`` labelled retrievals spread over ``span_days``.

    Queue lengths, occupancy and staffing are drawn per episode rather than
    swept on a grid, so the resulting dataset has the correlated, uneven shape
    of real traffic instead of an evenly spaced lattice that is much easier to
    fit than anything the platform will see.
    """
    if episodes <= 0:
        raise ValueError("episodes must be positive")
    if not 0.0 < test_fraction < 1.0:
        raise ValueError("test_fraction must be strictly between 0 and 1")

    rng = np.random.default_rng(seed)
    start = start or datetime(2026, 1, 1, 0, 0)

    # Timestamps are drawn uniformly across the span and then sorted, so the
    # temporal split below is a real "later period" rather than a random subset
    # that happens to be labelled as one.
    offsets = np.sort(rng.uniform(0.0, span_days * 86_400.0, size=episodes))

    rows: list[RetrievalEpisode] = []
    for offset in offsets:
        when = start + timedelta(seconds=float(offset))
        # Demand is bursty: most requests arrive alone or in twos, with
        # occasional rushes. A geometric draw gives that shape.
        queue_size = int(rng.geometric(0.45))
        queue_size = max(1, min(queue_size, 12))
        queue_position = int(rng.integers(1, queue_size + 1))

        zone_index = int(rng.integers(0, len(ZONE_PROFILES)))
        zone_profile = ZONE_PROFILES[zone_index]
        # Give the row a zone code rather than leaving it as a bare index: the
        # index is what the model sees, but a human reading exported history
        # needs the code, and the service records the code on every prediction.
        zone_code = zone_codes[zone_index % len(zone_codes)]

        capacity = int(zone_profile["capacity"])
        occupancy = int(rng.integers(0, capacity + 1))
        occ_pct = 100.0 * occupancy / capacity

        # Staffing follows the clock: fewer valets overnight and at weekends.
        hour = when.hour
        if 0 <= hour < 6:
            valets = int(rng.integers(1, 3))
        elif 6 <= hour < 22:
            valets = int(rng.integers(3, 9))
        else:
            valets = int(rng.integers(2, 5))
        if when.weekday() >= 5:
            valets = max(1, valets - 2)

        flagged = bool(rng.random() < 0.08)

        # The zone's own historical mean is itself a feature the platform can
        # compute from past rows. It is derived from the generator's parameters
        # plus per-zone drift, so it is informative but not a copy of the answer.
        historical_mean = (
            (BASE_WALK_MINUTES + BASE_DRIVE_MINUTES) * zone_profile["walk_scale"]
            + QUEUE_SERVICE_MINUTES * 1.3
            + rng.normal(0.0, 0.4)
        )

        context = RetrievalContext(
            queue_size=queue_size,
            queue_position=queue_position,
            active_valets=valets,
            zone_capacity=capacity,
            zone_occupancy=occupancy,
            requested_at=when,
            historical_zone_mean_minutes=max(1.0, historical_mean),
            vehicle_flagged=flagged,
        )
        features = extract_features(context)

        deterministic = _true_minutes(
            queue_position=queue_position,
            active_valets=valets,
            zone_profile=zone_profile,
            occupancy_percent=occ_pct,
            requested_at=when,
            vehicle_flagged=flagged,
        )
        # Lognormal noise: retrieval times are right-skewed, since a job can run
        # long but cannot go below the physical minimum. sigma 0.18 leaves a
        # floor under the achievable MAE.
        noise = float(np.exp(rng.normal(0.0, 0.18)))
        actual = max(1.0, deterministic * noise)

        rows.append(
            RetrievalEpisode(
                features=features,
                actual_minutes=actual,
                requested_at=when,
                zone_index=zone_index,
                zone_code=zone_code,
                vehicle_status="FLAGGED" if flagged else "IN_CUSTODY",
                zone_occupancy=occupancy,
            )
        )

    return _assemble(rows, test_fraction)


def zone_profile_for(zone_code: str) -> dict[str, float]:
    """The generator's profile for a zone code.

    Exposed so the prediction service can supply a plausible
    ``historical_zone_mean_minutes`` when a zone has no recorded history yet,
    rather than guessing or refusing. The service prefers real history and falls
    back to this.
    """
    return ZONE_PROFILES[_zone_index_for(zone_code)]


__all__ = [
    "RetrievalDataset",
    "RetrievalEpisode",
    "generate_history",
    "load_history",
    "zone_profile_for",
]

def _assemble(episodes: Sequence[RetrievalEpisode], test_fraction: float) -> RetrievalDataset:
    """Build the feature matrix and the temporal split for a set of episodes.

    Shared by ``generate_history`` and ``load_history`` on purpose. If each
    built its own matrix, the two would drift the moment a feature was added or
    reordered, and a model trained on one would be scored on the other.
    """
    X = np.array(
        [[row.features[name] for name in RETRIEVAL_FEATURE_COLUMNS] for row in episodes],
        dtype=float,
    )
    y = np.array([row.actual_minutes for row in episodes], dtype=float)

    # Temporal split: the last ``test_fraction`` of the span is held out. Rows
    # arrive time-ordered, so this is a genuinely later period rather than a
    # random subset dressed up as one.
    cutoff_index = int(len(episodes) * (1.0 - test_fraction))
    test_mask = np.zeros(len(episodes), dtype=bool)
    test_mask[cutoff_index:] = True

    return RetrievalDataset(
        episodes=tuple(episodes),
        X=X,
        y=y,
        test_mask=test_mask,
        generated_at=datetime.now().isoformat(timespec="seconds"),
    )


def load_history(path: str | Path) -> RetrievalDataset:
    """Read back a history written by ``generate_retrieval_history.py``.

    Training regenerates deterministically from a seed by default, which is
    usually preferable. But being able to fit the exact rows that were inspected
    and shared matters when someone asks which data produced a given artifact:
    regeneration is only equivalent if every generator constant is unchanged,
    and this makes the link explicit instead of assumed.

    Raises on a file whose feature order differs from this build's, for the same
    reason ``RetrievalModel.load`` refuses a mismatched artifact -- applying the
    right columns to the wrong data produces confident nonsense.
    """
    source = Path(path)
    if not source.exists():
        raise FileNotFoundError(f"no retrieval history at {source}")

    payload = json.loads(source.read_text(encoding="utf-8"))
    columns = payload.get("feature_columns")
    if columns is not None and tuple(columns) != RETRIEVAL_FEATURE_COLUMNS:
        raise ValueError(
            "history was generated with a different feature set; regenerate it. "
            f"file={list(columns)} code={list(RETRIEVAL_FEATURE_COLUMNS)}"
        )

    episodes: list[RetrievalEpisode] = []
    for row in payload.get("rows") or []:
        # The model inputs live in the feature columns; the three provenance
        # fields sit beside them. Reading each from where ``as_row`` actually
        # writes it keeps this honest to the real schema.
        episodes.append(
            RetrievalEpisode(
                features={name: float(row[name]) for name in RETRIEVAL_FEATURE_COLUMNS},
                actual_minutes=float(row["actual_retrieval_minutes"]),
                requested_at=datetime.fromisoformat(row["requested_at"]),
                zone_index=int(row["zone_index"]),
                zone_code=str(row.get("zone_code", "")),
                vehicle_status=str(row.get("vehicle_status", "IN_CUSTODY")),
                zone_occupancy=int(row.get("zone_occupancy", 0)),
            )
        )
    if not episodes:
        raise ValueError(f"{source} contains no rows")

    test_fraction = float((payload.get("generator") or {}).get("test_fraction", 0.25))
    # The split is recomputed from the loaded rows rather than read from a
    # stored flag, so it is always the latest slice of whatever was loaded.
    return _assemble(episodes, test_fraction)
